def book_reservation(user_id, origin, destination, flight_type, cabin, flights, passengers, payment_methods, total_baggages, nonfree_baggages, insurance, **_extra):
    import json, os, datetime, time, random, string
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0364000" if __import__("os").path.isdir("./environment_mix/0364000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "book_reservation"

    def _append_audit(status, error_code=None):
        audits = _load("audit_log.json")
        if not isinstance(audits, list):
            audits = []
        audits.append({
            "id": "aud_" + "".join(random.choice(string.ascii_lowercase + string.digits) for _ in range(12)),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("audit_log.json", audits)

    def _rate_limit_check_and_record_on_return(status, error_code=None):
        _append_audit(status, error_code)

    # --- validation helpers ---
    def _is_iata(s):
        return isinstance(s, str) and len(s) == 3 and s.isalpha() and s.upper() == s

    def _is_date(s):
        if not isinstance(s, str):
            return False
        try:
            datetime.datetime.strptime(s, "%Y-%m-%d")
            return True
        except ValueError:
            return False

    def _now():
        return datetime.datetime.utcnow().isoformat() + "Z"

    def _gen_res_id(existing):
        # 6 chars base32-ish, avoid collisions
        alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"
        for _ in range(2000):
            rid = "".join(random.choice(alphabet) for _ in range(6))
            if rid not in existing:
                return rid
        return None

    # Basic request validation
    if not isinstance(user_id, str) or not user_id:
        _rate_limit_check_and_record_on_return("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "user_id must be a non-empty string", field="user_id")
    if not _is_iata(origin):
        _rate_limit_check_and_record_on_return("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "origin must be a 3-letter uppercase IATA code", field="origin")
    if not _is_iata(destination):
        _rate_limit_check_and_record_on_return("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "destination must be a 3-letter uppercase IATA code", field="destination")
    if origin == destination:
        _rate_limit_check_and_record_on_return("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "origin and destination must differ", field="destination")

    if flight_type not in ("one_way", "round_trip"):
        _rate_limit_check_and_record_on_return("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "invalid flight_type", field="flight_type", allowed=["one_way", "round_trip"])
    if cabin not in ("basic_economy", "economy", "business"):
        _rate_limit_check_and_record_on_return("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "invalid cabin", field="cabin", allowed=["basic_economy", "economy", "business"])
    if insurance not in ("yes", "no"):
        _rate_limit_check_and_record_on_return("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "invalid insurance", field="insurance", allowed=["yes", "no"])

    if not isinstance(total_baggages, int) or total_baggages < 0:
        _rate_limit_check_and_record_on_return("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "total_baggages must be a non-negative integer", field="total_baggages")
    if not isinstance(nonfree_baggages, int) or nonfree_baggages < 0:
        _rate_limit_check_and_record_on_return("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "nonfree_baggages must be a non-negative integer", field="nonfree_baggages")
    if nonfree_baggages > total_baggages:
        _rate_limit_check_and_record_on_return("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "nonfree_baggages cannot exceed total_baggages", field="nonfree_baggages")

    if not isinstance(flights, list) or len(flights) == 0:
        _rate_limit_check_and_record_on_return("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "flights must be a non-empty array", field="flights")
    for i, seg in enumerate(flights):
        if not isinstance(seg, dict):
            _rate_limit_check_and_record_on_return("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "each flights item must be an object", field=f"flights[{i}]")
        if "flight_number" not in seg or "date" not in seg:
            _rate_limit_check_and_record_on_return("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "each flight must include flight_number and date", field=f"flights[{i}]")
        if not isinstance(seg["flight_number"], str) or not seg["flight_number"]:
            _rate_limit_check_and_record_on_return("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "flight_number must be a non-empty string", field=f"flights[{i}].flight_number")
        if not _is_date(seg["date"]):
            _rate_limit_check_and_record_on_return("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "date must be YYYY-MM-DD", field=f"flights[{i}].date")

    if not isinstance(passengers, list) or len(passengers) == 0:
        _rate_limit_check_and_record_on_return("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "passengers must be a non-empty array", field="passengers")
    for i, p in enumerate(passengers):
        if not isinstance(p, dict):
            _rate_limit_check_and_record_on_return("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "each passengers item must be an object", field=f"passengers[{i}]")
        for k in ("first_name", "last_name", "dob"):
            if k not in p:
                _rate_limit_check_and_record_on_return("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"passenger missing {k}", field=f"passengers[{i}].{k}")
            if not isinstance(p[k], str) or not p[k]:
                _rate_limit_check_and_record_on_return("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"passenger {k} must be a non-empty string", field=f"passengers[{i}].{k}")
        if not _is_date(p["dob"]):
            _rate_limit_check_and_record_on_return("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "passenger dob must be YYYY-MM-DD", field=f"passengers[{i}].dob")

    if not isinstance(payment_methods, list) or len(payment_methods) == 0:
        _rate_limit_check_and_record_on_return("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "payment_methods must be a non-empty array", field="payment_methods")
    for i, pm in enumerate(payment_methods):
        if not isinstance(pm, dict):
            _rate_limit_check_and_record_on_return("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "each payment_methods item must be an object", field=f"payment_methods[{i}]")
        if "payment_id" not in pm or "amount" not in pm:
            _rate_limit_check_and_record_on_return("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "each payment method must include payment_id and amount", field=f"payment_methods[{i}]")
        if not isinstance(pm["payment_id"], str) or not pm["payment_id"]:
            _rate_limit_check_and_record_on_return("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "payment_id must be a non-empty string", field=f"payment_methods[{i}].payment_id")
        if not isinstance(pm["amount"], (int, float)):
            _rate_limit_check_and_record_on_return("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "amount must be numeric", field=f"payment_methods[{i}].amount")
        if pm["amount"] <= 0:
            _rate_limit_check_and_record_on_return("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "amount must be positive", field=f"payment_methods[{i}].amount")

    # Load store (collections are arrays of objects)
    flights_rows = _load("flights.json")
    reservations_rows = _load("reservations.json")
    users_rows = _load("users.json")
    if not isinstance(flights_rows, list): flights_rows = []
    if not isinstance(reservations_rows, list): reservations_rows = []
    if not isinstance(users_rows, list): users_rows = []

    # Find user by inferred key: users have no explicit id field in schema, but reservations reference users.id.
    # We therefore accept either row['id'] == user_id, or row['email'] == user_id, or row['user_id'] == user_id.
    user = None
    for u in users_rows:
        if isinstance(u, dict) and (u.get("id") == user_id or u.get("user_id") == user_id or u.get("email") == user_id):
            user = u
            break
    if user is None:
        _rate_limit_check_and_record_on_return("error", "NOT_FOUND")
        return _err("NOT_FOUND", "user not found", user_id=user_id)

    user_payment_methods = user.get("payment_methods")
    if not isinstance(user_payment_methods, (list, dict)):
        user_payment_methods = []

    def _find_user_payment(pid):
        if isinstance(user_payment_methods, dict):
            # support legacy dict keyed by id
            v = user_payment_methods.get(pid)
            if isinstance(v, dict):
                return v
            return None
        for x in user_payment_methods:
            if isinstance(x, dict) and x.get("id") == pid:
                return x
        return None

    # Validate payments belong to user and balances
    requested_total = 0
    for pm in payment_methods:
        requested_total += float(pm["amount"])

    # Calculate itinerary and seat availability; also compute total fare
    pax_count = len(passengers)
    computed_flights = []
    total_fare = 0

    # flights.json schema: each row has flight_number + dates (object). We'll search by flight_number match.
    def _get_flight_row(fn):
        for fr in flights_rows:
            if isinstance(fr, dict) and fr.get("flight_number") == fn:
                return fr
        return None

    # We will only allow booking if all segments exist & are available & have enough seats
    for seg in flights:
        fn = seg["flight_number"]
        dt = seg["date"]
        fr = _get_flight_row(fn)
        if fr is None:
            _rate_limit_check_and_record_on_return("error", "NOT_FOUND")
            return _err("NOT_FOUND", "flight not found", flight_number=fn)
        dates = fr.get("dates")
        if not isinstance(dates, dict) or dt not in dates or not isinstance(dates.get(dt), dict):
            _rate_limit_check_and_record_on_return("error", "NOT_FOUND")
            return _err("NOT_FOUND", "flight not found on date", flight_number=fn, date=dt)
        dd = dates[dt]
        status = dd.get("status")
        if status != "available":
            _rate_limit_check_and_record_on_return("error", "CONFLICT")
            return _err("CONFLICT", "flight is not available on requested date", flight_number=fn, date=dt, status=status)
        avail = dd.get("available_seats")
        prices = dd.get("prices")
        if not isinstance(avail, dict) or not isinstance(prices, dict):
            _rate_limit_check_and_record_on_return("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "flight date record missing availability/prices", flight_number=fn, date=dt)
        if cabin not in avail or cabin not in prices:
            _rate_limit_check_and_record_on_return("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cabin not offered for flight", flight_number=fn, cabin=cabin)
        if not isinstance(avail.get(cabin), int) or avail.get(cabin) < pax_count:
            _rate_limit_check_and_record_on_return("error", "CONFLICT")
            return _err("CONFLICT", "not enough seats", flight_number=fn, date=dt, cabin=cabin, requested=pax_count, available=avail.get(cabin))
        if not isinstance(prices.get(cabin), int) or prices.get(cabin) < 0:
            _rate_limit_check_and_record_on_return("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "invalid price for flight cabin", flight_number=fn, date=dt, cabin=cabin)

        seg_price = int(prices[cabin])
        total_fare += seg_price * pax_count
        computed_flights.append({
            "origin": fr.get("origin"),
            "destination": fr.get("destination"),
            "flight_number": fn,
            "date": dt,
            "price": seg_price
        })

    # Simple extras pricing (not specified by rules; keep 0 to avoid fabricating vendor logic)
    extras_total = 0
    total_due = total_fare + extras_total

    # Validate payment total equals total_due
    if abs(requested_total - float(total_due)) > 0.0001:
        _rate_limit_check_and_record_on_return("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "payment amounts must sum to the total price", total_due=total_due, payment_sum=requested_total)

    # Validate each payment method exists and has balance if gift_card/certificate
    for pm in payment_methods:
        pid = pm["payment_id"]
        amt = float(pm["amount"])
        instrument = _find_user_payment(pid)
        if instrument is None:
            _rate_limit_check_and_record_on_return("error", "NOT_FOUND")
            return _err("NOT_FOUND", "payment method not found for user", payment_id=pid, user_id=user_id)
        src = instrument.get("source")
        if src in ("gift_card", "certificate"):
            bal = instrument.get("amount")
            if not isinstance(bal, int):
                _rate_limit_check_and_record_on_return("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "stored payment instrument missing integer amount", payment_id=pid)
            if bal < int(round(amt)):
                _rate_limit_check_and_record_on_return("error", "CONFLICT")
                return _err("CONFLICT", "insufficient balance", payment_id=pid, balance=bal, required=int(round(amt)))

    # Generate reservation id and persist updates: seats decrement, balances decrement, reservation inserted
    existing_ids = set()
    for r in reservations_rows:
        if isinstance(r, dict) and isinstance(r.get("reservation_id"), str):
            existing_ids.add(r["reservation_id"])
    rid = _gen_res_id(existing_ids)
    if rid is None:
        _rate_limit_check_and_record_on_return("error", "CONFLICT")
        return _err("CONFLICT", "could not allocate reservation id")

    # Decrement seats
    for seg in flights:
        fn = seg["flight_number"]
        dt = seg["date"]
        fr = _get_flight_row(fn)
        dd = fr["dates"][dt]
        dd["available_seats"][cabin] = int(dd["available_seats"][cabin]) - pax_count

    # Decrement instrument balances if applicable
    # Also record payment history entries as integers (cents assumed by schema integer; we store rounded)
    payment_history = []
    for pm in payment_methods:
        pid = pm["payment_id"]
        amt_i = int(round(float(pm["amount"])))
        instrument = _find_user_payment(pid)
        src = instrument.get("source")
        if src in ("gift_card", "certificate"):
            instrument["amount"] = int(instrument["amount"]) - amt_i
        payment_history.append({"payment_id": pid, "amount": amt_i})

    reservation = {
        "reservation_id": rid,
        "user_id": user_id,
        "origin": origin,
        "destination": destination,
        "flight_type": flight_type,
        "cabin": cabin,
        "flights": computed_flights,
        "passengers": passengers,
        "payment_history": payment_history,
        "created_at": _now(),
        "total_baggages": total_baggages,
        "nonfree_baggages": nonfree_baggages,
        "insurance": insurance
    }
    reservations_rows.append(reservation)

    # Link reservation in user record if it has reservations array
    if isinstance(user.get("reservations"), list):
        if rid not in user["reservations"]:
            user["reservations"].append(rid)

    _save("flights.json", flights_rows)
    _save("users.json", users_rows)
    _save("reservations.json", reservations_rows)

    _rate_limit_check_and_record_on_return("success", None)
    return {"reservation": reservation}

