def calculate(expression):
    import json, os
    data = {'flights': json.load(open(os.path.join(_DB, 'flights.json'), encoding='utf-8')), 'reservations': json.load(open(os.path.join(_DB, 'reservations.json'), encoding='utf-8')), 'users': json.load(open(os.path.join(_DB, 'users.json'), encoding='utf-8'))}
    if not all(char in "0123456789+-*/(). " for char in expression):
        return "Error: invalid characters in expression"
    try:
        return str(round(float(eval(expression, {"__builtins__": None}, {})), 2))
    except Exception as e:
        return f"Error: {e}"

def cancel_reservation(reservation_id, **_extra):
    import json, os, datetime, time, random, string
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0364000" if __import__("os").path.isdir("./environment_mix/0364000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "cancel_reservation"

    def _append_audit(status, error_code=None):
        audits = _load("audit_log.json")
        if not isinstance(audits, list):
            audits = []
        audits.append({
            "id": "aud_" + "".join(random.choice(string.ascii_lowercase + string.digits) for _ in range(12)),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("audit_log.json", audits)

    if not isinstance(reservation_id, str) or not reservation_id:
        _append_audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "reservation_id must be a non-empty string", field="reservation_id")

    flights_rows = _load("flights.json")
    reservations_rows = _load("reservations.json")
    users_rows = _load("users.json")
    if not isinstance(flights_rows, list): flights_rows = []
    if not isinstance(reservations_rows, list): reservations_rows = []
    if not isinstance(users_rows, list): users_rows = []

    res = None
    for r in reservations_rows:
        if isinstance(r, dict) and r.get("reservation_id") == reservation_id:
            res = r
            break
    if res is None:
        _append_audit("error", "NOT_FOUND")
        return _err("NOT_FOUND", "reservation not found", reservation_id=reservation_id)

    # Cancelability: if already cancelled => invalid transition
    if res.get("status") == "cancelled":
        _append_audit("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "reservation already cancelled", reservation_id=reservation_id)

    # Restore seats for each segment if possible
    pax_count = len(res.get("passengers") or [])
    cabin = res.get("cabin")
    if cabin not in ("basic_economy", "economy", "business"):
        _append_audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "reservation has invalid cabin", reservation_id=reservation_id)

    def _get_flight_row(fn):
        for fr in flights_rows:
            if isinstance(fr, dict) and fr.get("flight_number") == fn:
                return fr
        return None

    for seg in (res.get("flights") or []):
        if not isinstance(seg, dict):
            continue
        fn = seg.get("flight_number")
        dt = seg.get("date")
        if not isinstance(fn, str) or not isinstance(dt, str):
            continue
        fr = _get_flight_row(fn)
        if fr and isinstance(fr.get("dates"), dict) and dt in fr["dates"] and isinstance(fr["dates"][dt], dict):
            dd = fr["dates"][dt]
            if isinstance(dd.get("available_seats"), dict) and isinstance(dd["available_seats"].get(cabin), int):
                dd["available_seats"][cabin] = dd["available_seats"][cabin] + pax_count

    # Refund payment instruments by reversing positive charges
    # We will only reverse payments that are positive amounts in history.
    user_id = res.get("user_id")
    user = None
    for u in users_rows:
        if isinstance(u, dict) and (u.get("id") == user_id or u.get("user_id") == user_id or u.get("email") == user_id):
            user = u
            break

    user_payment_methods = user.get("payment_methods") if isinstance(user, dict) else None
    def _find_user_payment(pid):
        if isinstance(user_payment_methods, dict):
            v = user_payment_methods.get(pid)
            if isinstance(v, dict):
                return v
            return None
        if isinstance(user_payment_methods, list):
            for x in user_payment_methods:
                if isinstance(x, dict) and x.get("id") == pid:
                    return x
        return None

    payment_history = res.get("payment_history")
    if not isinstance(payment_history, list):
        payment_history = []
        res["payment_history"] = payment_history

    refunds = []
    for p in payment_history:
        if not isinstance(p, dict):
            continue
        pid = p.get("payment_id")
        amt = p.get("amount")
        if not isinstance(pid, str) or not isinstance(amt, int):
            continue
        if amt <= 0:
            continue
        # credit back gift cards/certificates if those instruments exist
        inst = _find_user_payment(pid)
        if inst and inst.get("source") in ("gift_card", "certificate") and isinstance(inst.get("amount"), int):
            inst["amount"] = inst["amount"] + amt
        refunds.append({"payment_id": pid, "amount": -amt})

    if refunds:
        res["payment_history"] = payment_history + refunds

    res["status"] = "cancelled"
    res["cancelled_at"] = datetime.datetime.utcnow().isoformat() + "Z"

    _save("flights.json", flights_rows)
    _save("users.json", users_rows)
    _save("reservations.json", reservations_rows)

    _append_audit("success", None)
    return {"reservation": res}

