        _append_audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "total_baggages must be a non-negative integer", field="total_baggages")
    if not isinstance(nonfree_baggages, int) or nonfree_baggages < 0:
        _append_audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "nonfree_baggages must be a non-negative integer", field="nonfree_baggages")
    if nonfree_baggages > total_baggages:
        _append_audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "nonfree_baggages cannot exceed total_baggages", field="nonfree_baggages")
    if not isinstance(payment_id, str) or not payment_id:
        _append_audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "payment_id must be a non-empty string", field="payment_id")

    reservations_rows = _load("reservations.json")
    users_rows = _load("users.json")
    if not isinstance(reservations_rows, list): reservations_rows = []
    if not isinstance(users_rows, list): users_rows = []

    res = None
    for r in reservations_rows:
        if isinstance(r, dict) and r.get("reservation_id") == reservation_id:
            res = r
            break
    if res is None:
        _append_audit("error", "NOT_FOUND")
        return _err("NOT_FOUND", "reservation not found", reservation_id=reservation_id)
    if res.get("status") == "cancelled":
        _append_audit("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "cannot modify a cancelled reservation", reservation_id=reservation_id)

    user_id = res.get("user_id")
    user = None
    for u in users_rows:
        if isinstance(u, dict) and (u.get("id") == user_id or u.get("user_id") == user_id or u.get("email") == user_id):
            user = u
            break
    if user is None:
        _append_audit("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "no user context available to authorize modification")

    pm = user.get("payment_methods")
    def _find_user_payment(pid):
        if isinstance(pm, dict):
            v = pm.get(pid)
            return v if isinstance(v, dict) else None
        if isinstance(pm, list):
            for x in pm:
                if isinstance(x, dict) and x.get("id") == pid:
                    return x
        return None

    inst = _find_user_payment(payment_id)
    if inst is None:
        _append_audit("error", "NOT_FOUND")
        return _err("NOT_FOUND", "payment method not found for user", payment_id=payment_id, user_id=user_id)

    old_nonfree = res.get("nonfree_baggages")
    if not isinstance(old_nonfree, int):
        old_nonfree = 0

    # Pricing rule (carried from broken code): $50 per newly-added nonfree baggage
    delta_nonfree = max(0, nonfree_baggages - old_nonfree)
    charge = 50 * delta_nonfree

    src = inst.get("source")
    if src == "certificate":
        _append_audit("error", "CONFLICT")
        return _err("CONFLICT", "certificate cannot be used to update reservation", payment_id=payment_id)
    if src == "gift_card":
