        if not isinstance(bal, int):
            _append_audit("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "gift card missing balance", payment_id=payment_id)
        if bal < charge:
            _append_audit("error", "CONFLICT")
            return _err("CONFLICT", "gift card balance is not enough", payment_id=payment_id, balance=bal, required=charge)

    # Apply mutation
    res["total_baggages"] = total_baggages
    res["nonfree_baggages"] = nonfree_baggages
    res["updated_at"] = datetime.datetime.utcnow().isoformat() + "Z"

    if charge > 0:
        if src == "gift_card":
            inst["amount"] = int(inst["amount"]) - charge
        ph = res.get("payment_history")
        if not isinstance(ph, list):
            ph = []
            res["payment_history"] = ph
        ph.append({"payment_id": payment_id, "amount": int(charge)})

    _save("users.json", users_rows)
    _save("reservations.json", reservations_rows)
    _append_audit("success", None)
    return {"reservation": res}

