            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("audit_log.json", audits)

    def _is_date(s):
        if not isinstance(s, str):
            return False
        try:
            datetime.datetime.strptime(s, "%Y-%m-%d")
            return True
        except ValueError:
            return False

    if not isinstance(reservation_id, str) or not reservation_id:
        _append_audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "reservation_id must be a non-empty string", field="reservation_id")
    if cabin not in ("basic_economy", "economy", "business"):
        _append_audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "invalid cabin", field="cabin", allowed=["basic_economy", "economy", "business"])
    if not isinstance(payment_id, str) or not payment_id:
        _append_audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "payment_id must be a non-empty string", field="payment_id")
    if not isinstance(flights, list) or len(flights) == 0:
        _append_audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "flights must be a non-empty array", field="flights")

    for i, seg in enumerate(flights):
        if not isinstance(seg, dict) or "flight_number" not in seg or "date" not in seg:
            _append_audit("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "each flight must include flight_number and date", field=f"flights[{i}]")
        if not isinstance(seg["flight_number"], str) or not seg["flight_number"]:
            _append_audit("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "flight_number must be a non-empty string", field=f"flights[{i}].flight_number")
        if not _is_date(seg["date"]):
            _append_audit("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "date must be YYYY-MM-DD", field=f"flights[{i}].date")

    flights_rows = _load("flights.json")
    reservations_rows = _load("reservations.json")
    users_rows = _load("users.json")
    if not isinstance(flights_rows, list): flights_rows = []
    if not isinstance(reservations_rows, list): reservations_rows = []
    if not isinstance(users_rows, list): users_rows = []

    res = None
    for r in reservations_rows:
        if isinstance(r, dict) and r.get("reservation_id") == reservation_id:
            res = r
            break
    if res is None:
        _append_audit("error", "NOT_FOUND")
        return _err("NOT_FOUND", "reservation not found", reservation_id=reservation_id)
    if res.get("status") == "cancelled":
        _append_audit("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "cannot modify a cancelled reservation", reservation_id=reservation_id)

    user_id = res.get("user_id")
    user = None
    for u in users_rows:
        if isinstance(u, dict) and (u.get("id") == user_id or u.get("user_id") == user_id or u.get("email") == user_id):
            user = u
            break
    if user is None:
        _append_audit("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "no user context available to authorize modification")

    pm = user.get("payment_methods")
    def _find_user_payment(pid):
        if isinstance(pm, dict):
            v = pm.get(pid)
            return v if isinstance(v, dict) else None
        if isinstance(pm, list):
            for x in pm:
                if isinstance(x, dict) and x.get("id") == pid:
                    return x
        return None

    inst = _find_user_payment(payment_id)
    if inst is None:
        _append_audit("error", "NOT_FOUND")
        return _err("NOT_FOUND", "payment method not found for user", payment_id=payment_id, user_id=user_id)

    pax_count = len(res.get("passengers") or [])
    if pax_count <= 0:
        _append_audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "reservation has no passengers; cannot reprice", reservation_id=reservation_id)

    def _get_flight_row(fn):
        for fr in flights_rows:
            if isinstance(fr, dict) and fr.get("flight_number") == fn:
                return fr
        return None

    # compute new itinerary total, check availability; preserve previous price if same segment+same cabin
    new_flights_in = deepcopy(flights)
    old_segments = {(f.get("flight_number"), f.get("date"), res.get("cabin")): f for f in (res.get("flights") or []) if isinstance(f, dict)}
    new_segments_out = []
    new_total = 0

    for seg in new_flights_in:
        key = (seg.get("flight_number"), seg.get("date"), cabin)
        if key in old_segments and isinstance(old_segments[key].get("price"), int):
            old = old_segments[key]
            price = int(old["price"])
            new_total += price * pax_count
            new_segments_out.append({
                "origin": old.get("origin"),
                "destination": old.get("destination"),
                "flight_number": old.get("flight_number"),
                "date": old.get("date"),
                "price": price
            })
            continue

        fn = seg["flight_number"]
        dt = seg["date"]
        fr = _get_flight_row(fn)
        if fr is None:
            _append_audit("error", "NOT_FOUND")
            return _err("NOT_FOUND", "flight not found", flight_number=fn)
        dates = fr.get("dates")
        if not isinstance(dates, dict) or dt not in dates or not isinstance(dates.get(dt), dict):
            _append_audit("error", "NOT_FOUND")
            return _err("NOT_FOUND", "flight not found on date", flight_number=fn, date=dt)
        dd = dates[dt]
        if dd.get("status") != "available":
            _append_audit("error", "CONFLICT")
            return _err("CONFLICT", "flight is not available on requested date", flight_number=fn, date=dt, status=dd.get("status"))
        avail = dd.get("available_seats")
        prices = dd.get("prices")
        if not isinstance(avail, dict) or not isinstance(prices, dict):
            _append_audit("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "flight date record missing availability/prices", flight_number=fn, date=dt)
        if not isinstance(avail.get(cabin), int) or avail.get(cabin) < pax_count:
            _append_audit("error", "CONFLICT")
            return _err("CONFLICT", "not enough seats", flight_number=fn, date=dt, cabin=cabin, requested=pax_count, available=avail.get(cabin))
        if not isinstance(prices.get(cabin), int) or prices.get(cabin) < 0:
            _append_audit("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "invalid price for flight cabin", flight_number=fn, date=dt, cabin=cabin)
        price = int(prices[cabin])
        new_total += price * pax_count
        new_segments_out.append({
            "origin": fr.get("origin"),
            "destination": fr.get("destination"),
            "flight_number": fn,
            "date": dt,
            "price": price
        })

    old_total = 0
    for f in (res.get("flights") or []):
        if isinstance(f, dict) and isinstance(f.get("price"), int):
            old_total += int(f["price"]) * pax_count

    delta = new_total - old_total
    if delta < 0:
        # allow but we won't auto-refund; keep behavior conservative
        delta = 0

    src = inst.get("source")
    if delta > 0:
        if src == "certificate":
            _append_audit("error", "CONFLICT")
            return _err("CONFLICT", "certificate cannot be used to update reservation", payment_id=payment_id)
        if src == "gift_card":
            bal = inst.get("amount")
            if not isinstance(bal, int):
                _append_audit("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "gift card missing balance", payment_id=payment_id)
            if bal < delta:
                _append_audit("error", "CONFLICT")
                return _err("CONFLICT", "gift card balance is not enough", payment_id=payment_id, balance=bal, required=delta)

    # Adjust seat inventories: restore old segments, decrement new segments
    # Restoration first
    old_cabin = res.get("cabin")
    def _adjust(fn, dt, cab, amount):
        fr = _get_flight_row(fn)
        if fr and isinstance(fr.get("dates"), dict) and dt in fr["dates"] and isinstance(fr["dates"][dt], dict):
            dd = fr["dates"][dt]
            if isinstance(dd.get("available_seats"), dict) and isinstance(dd["available_seats"].get(cab), int):
                dd["available_seats"][cab] = dd["available_seats"][cab] + amount

    for f in (res.get("flights") or []):
        if isinstance(f, dict) and isinstance(f.get("flight_number"), str) and isinstance(f.get("date"), str) and old_cabin in ("basic_economy", "economy", "business"):
            _adjust(f["flight_number"], f["date"], old_cabin, pax_count)

    # Decrement for new
    for f in new_segments_out:
        if isinstance(f, dict) and isinstance(f.get("flight_number"), str) and isinstance(f.get("date"), str):
            _adjust(f["flight_number"], f["date"], cabin, -pax_count)

    # Charge if needed
    if delta > 0:
        if src == "gift_card":
            inst["amount"] = int(inst["amount"]) - int(delta)
        ph = res.get("payment_history")
        if not isinstance(ph, list):
            ph = []
            res["payment_history"] = ph
        ph.append({"payment_id": payment_id, "amount": int(delta)})

    res["cabin"] = cabin
    res["flights"] = new_segments_out
    res["updated_at"] = datetime.datetime.utcnow().isoformat() + "Z"

    _save("flights.json", flights_rows)
    _save("users.json", users_rows)
    _save("reservations.json", reservations_rows)

    _append_audit("success", None)
    return {"reservation": res}

def update_reservation_passengers(reservation_id, passengers, **_extra):
    import json, os, datetime, time, random, string
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0364000" if __import__("os").path.isdir("./environment_mix/0364000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_reservation_passengers"

    def _append_audit(status, error_code=None):
        audits = _load("audit_log.json")
        if not isinstance(audits, list):
            audits = []
        audits.append({
            "id": "aud_" + "".join(random.choice(string.ascii_lowercase + string.digits) for _ in range(12)),
            "endpoint": endpoint,
            "status": status,
            "error_code": error_code,
            "timestamp": datetime.datetime.utcnow().isoformat() + "Z",
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("audit_log.json", audits)

    def _is_date(s):
        if not isinstance(s, str):
            return False
        try:
            datetime.datetime.strptime(s, "%Y-%m-%d")
            return True
        except ValueError:
            return False

    if not isinstance(reservation_id, str) or not reservation_id:
        _append_audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "reservation_id must be a non-empty string", field="reservation_id")
    if not isinstance(passengers, list) or len(passengers) == 0:
        _append_audit("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "passengers must be a non-empty array", field="passengers")

    for i, p in enumerate(passengers):
        if not isinstance(p, dict):
            _append_audit("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "each passengers item must be an object", field=f"passengers[{i}]")
        for k in ("first_name", "last_name", "dob"):
            if k not in p:
                _append_audit("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"passenger missing {k}", field=f"passengers[{i}].{k}")
            if not isinstance(p[k], str) or not p[k]:
                _append_audit("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"passenger {k} must be a non-empty string", field=f"passengers[{i}].{k}")
        if not _is_date(p["dob"]):
            _append_audit("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "passenger dob must be YYYY-MM-DD", field=f"passengers[{i}].dob")

    reservations_rows = _load("reservations.json")
    if not isinstance(reservations_rows, list): reservations_rows = []

    res = None
    for r in reservations_rows:
        if isinstance(r, dict) and r.get("reservation_id") == reservation_id:
            res = r
            break
    if res is None:
        _append_audit("error", "NOT_FOUND")
        return _err("NOT_FOUND", "reservation not found", reservation_id=reservation_id)
    if res.get("status") == "cancelled":
        _append_audit("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "cannot modify a cancelled reservation", reservation_id=reservation_id)

    # Allow passenger list replacement (do NOT enforce same length; tool description says updates list)
    res["passengers"] = passengers
    res["updated_at"] = datetime.datetime.utcnow().isoformat() + "Z"

    _save("reservations.json", reservations_rows)
    _append_audit("success", None)
    return {"reservation": res}
